// Do not edit by hand: change that file and run `node studio/panel/gen-data.mjs`.
// Street Rivals remote settings (public.sr_config, row id = 1, column value): the field rules.
// The ONE copy of these rules. The sr-admin Edge Function (handler.ts) checks every write with them, and the studio
// panel uses a generated copy (studio/panel/sr-rules.js, written by studio/panel/gen-data.mjs; do not edit that one).
//
// Strict on purpose: a value is accepted only when the game's own reader (src/street/remote.ts applyRemote) would take
// it exactly as written. The game quietly skips or rounds a bad value; the panel and the function refuse it instead,
// with the field name and a plain Turkish message. studio/panel/panel-check.mjs proves this on sample settings
// (accepted ⇔ applyRemote keeps it unchanged) and that SR_DEFAULTS equal remote.ts and the insert in street.sql.
// Keys, meaning and bounds: docs/STREET-RIVALS-UZAK-AYAR.md.

export const SR_DEFAULTS = {
  launch: '2026-10',
  races_per_ad: 5,
  series_levels: [30, 50, 80, 100],
  series_sets: {},
  ladder: { prize_base: 200, prize_growth: 1, flat_after: 15, flat_step: 0, boss_bonus: 1, fee_fixed: 100, fee_share: 0.2, replay_share: 0.75 },
  off: { nitro_ad: false, refund_ad: false, double_ad: false },
};
export const SR_KEYS = ['launch', 'races_per_ad', 'series_levels', 'series_sets', 'ladder', 'off'];
/** ladder key → [lowest, highest, whole number only] (remote.ts rounds the whole-number ones, so a fraction is refused) */
export const SR_LADDER = {
  prize_base: [50, 5000, false],
  prize_growth: [1, 1.6, false],
  flat_after: [5, 200, true],
  flat_step: [0, 0.5, false],
  boss_bonus: [1, 3, false],
  fee_fixed: [0, 100000, true],
  fee_share: [0, 0.9, false],
  replay_share: [0, 1, false],
};
export const SR_OFF = ['nitro_ad', 'refund_ad', 'double_ad'];
export const SR_LEVELS = 4;

const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
const fmt = (n) => String(n).replace('.', ',');

/** "YYYY-MM", year 2026–2100, month 01–12 (remote.ts and street.sql sr_private.launch() both read it so). null = fine. */
export function launchError(s) {
  if (typeof s !== 'string' || !/^\d{4}-(0[1-9]|1[0-2])$/.test(s)) return 'Ay "YYYY-AA" biçiminde olmalı (ör. 2026-10).';
  const y = Number(s.slice(0, 4));
  if (y < 2026 || y > 2100) return 'Yıl 2026 ile 2100 arasında olmalı.';
  return null;
}

/** The month a season start may use: this month or the next one (UTC, like the game's calendar). */
export function launchWindow(now = Date.now()) {
  const d = new Date(now);
  const m = (y, mo) => `${y + Math.floor(mo / 12)}-${String((mo % 12) + 1).padStart(2, '0')}`;
  return [m(d.getUTCFullYear(), d.getUTCMonth()), m(d.getUTCFullYear(), d.getUTCMonth() + 1)];
}

/** What the owner types to start a season (ASCII, so every keyboard has it). Compared after trim, case-blind. */
export const startPhrase = (month) => `BASLAT ${month}`;
export const phraseOk = (typed, month) => typeof typed === 'string' && typed.trim().toUpperCase() === startPhrase(month);

/**
 * The whole settings object (every key present; the panel always writes all of them) → { ok, value, errors }.
 * value is a clean copy in a fixed key order; errors: [{ field, msg }].
 */
export function checkSrConfig(v) {
  const errors = [];
  const bad = (field, msg) => errors.push({ field, msg });
  if (!isObj(v)) { bad('value', 'Ayarlar bir nesne olmalı.'); return { ok: false, value: null, errors }; }
  for (const k of Object.keys(v)) if (!SR_KEYS.includes(k)) bad(k, 'Bilinmeyen ayar: oyun bunu okumaz.');
  for (const k of SR_KEYS) if (!(k in v)) bad(k, 'Eksik.');
  const out = {};

  if ('launch' in v) {
    const e = launchError(v.launch);
    if (e) bad('launch', e); else out.launch = v.launch;
  }
  if ('races_per_ad' in v) {
    const n = v.races_per_ad;
    if (!isNum(n) || !Number.isInteger(n) || n < 1 || n > 30) bad('races_per_ad', '1 ile 30 arasında tam sayı olmalı.');
    else out.races_per_ad = n;
  }
  if ('series_levels' in v) {
    const l = v.series_levels;
    if (!Array.isArray(l) || l.length !== SR_LEVELS) bad('series_levels', `Tam ${SR_LEVELS} seviye olmalı.`);
    else {
      let okAll = true;
      l.forEach((x, i) => {
        if (!isNum(x) || !Number.isInteger(x) || x < 2 || x > 1000) { bad(`series_levels.${i}`, '2 ile 1000 arasında tam sayı olmalı.'); okAll = false; }
        else if (i > 0 && isNum(l[i - 1]) && x <= l[i - 1]) { bad(`series_levels.${i}`, 'Bir öncekinden büyük olmalı (küçükten büyüğe).'); okAll = false; }
      });
      if (okAll) out.series_levels = l.slice();
    }
  }
  if ('series_sets' in v) {
    const s = v.series_sets;
    if (!isObj(s)) bad('series_sets', 'Sezon → set eşleşmesi bir nesne olmalı.');
    else {
      const o = {};
      for (const [k, x] of Object.entries(s)) {
        if (!/^[1-9]\d{0,3}$/.test(k) || Number(k) > 1000) { bad(`series_sets.${k}`, 'Sezon numarası 1 ile 1000 arasında tam sayı olmalı.'); continue; }
        if (!isNum(x) || !Number.isInteger(x) || x < 0 || x > 1000) { bad(`series_sets.${k}`, 'Set numarası 0 ile 1000 arasında tam sayı olmalı.'); continue; }
        o[k] = x;
      }
      out.series_sets = Object.fromEntries(Object.entries(o).sort((a, b) => Number(a[0]) - Number(b[0])));
    }
  }
  if ('ladder' in v) {
    const l = v.ladder;
    if (!isObj(l)) bad('ladder', 'Merdiven ayarları bir nesne olmalı.');
    else {
      const o = {};
      for (const k of Object.keys(l)) if (!(k in SR_LADDER)) bad(`ladder.${k}`, 'Bilinmeyen ayar: oyun bunu okumaz.');
      for (const [k, [lo, hi, whole]] of Object.entries(SR_LADDER)) {
        const x = l[k];
        if (!(k in l)) { bad(`ladder.${k}`, 'Eksik.'); continue; }
        if (!isNum(x) || x < lo || x > hi || (whole && !Number.isInteger(x))) bad(`ladder.${k}`, `${fmt(lo)} ile ${fmt(hi)} arasında ${whole ? 'tam sayı' : 'sayı'} olmalı.`);
        else o[k] = x;
      }
      out.ladder = o;
    }
  }
  if ('off' in v) {
    const f = v.off;
    if (!isObj(f)) bad('off', 'Reklam ödülü anahtarları bir nesne olmalı.');
    else {
      const o = {};
      for (const k of Object.keys(f)) if (!SR_OFF.includes(k)) bad(`off.${k}`, 'Bilinmeyen ayar: oyun bunu okumaz.');
      for (const k of SR_OFF) {
        if (typeof f[k] !== 'boolean') bad(`off.${k}`, 'Açık ya da kapalı olmalı (true / false).');
        else o[k] = f[k];
      }
      out.off = o;
    }
  }
  return errors.length ? { ok: false, value: null, errors } : { ok: true, value: out, errors };
}
